<script lang="ts">
  import { getClient } from '$lib/api/client.svelte'
  import { profile } from '$lib/app/auth'

  import Markdown from '$lib/app/markdown/Markdown.svelte'
  import { escapeHtml } from '$lib/app/util.svelte'
  import CommentItem from '$lib/feature/comment/CommentItem.svelte'
  import type { InboxItem } from '$lib/feature/inbox'
  import PrivateMessage from '$lib/feature/inbox/PrivateMessage.svelte'
  import Avatar from '$lib/ui/generic/Avatar.svelte'
  import { publishedToDate } from '$lib/ui/util/date'
  import { Button, ButtonGroup, Expandable, Material } from 'mono-svelte'
  import RelativeDate from 'mono-svelte/util/RelativeDate.svelte'
  import {
    AtSymbol,
    ChatBubbleOvalLeftEllipsis,
    Eye,
    EyeSlash,
    Icon,
    PaperAirplane,
  } from 'svelte-hero-icons/dist'

  interface Props {
    item: InboxItem
  }

  let { item = $bindable() }: Props = $props()

  let loading = $state(false)

  async function markAsRead(isRead: boolean) {
    if (isRead && item.read) return

    loading = true

    switch (item.type) {
      case 'person_mention': {
        await getClient().markPersonMentionAsRead({
          person_mention_id: item.id,
          read: isRead,
        })
        break
      }
      case 'comment_reply': {
        await getClient().markCommentReplyAsRead({
          comment_reply_id: item.id,
          read: isRead,
        })
        break
      }
      case 'private_message': {
        await getClient().markPrivateMessageAsRead({
          private_message_id: item.id,
          read: isRead,
        })
      }
    }

    item.read = isRead
    if (profile.current.user)
      profile.inbox.notifications.inbox += isRead ? -1 : 1

    loading = false
  }
</script>

{#snippet actions()}
  <Button
    color={item.read ? 'secondary' : 'primary'}
    {loading}
    disabled={loading ||
      item.creator.id == profile.current.user?.local_user_view.person.id}
    onclick={(e: MouseEvent) => {
      e.stopPropagation()
      markAsRead(!item.read)
    }}
    size="sm"
    rounding="pill"
    class="shrink-0"
    icon={item.read ? EyeSlash : Eye}
  >
    {item.read
      ?'Mark as unread'
      :'Mark as read'}
  </Button>
  <Button
    href={item.type == 'private_message'
      ? `/inbox/messages/${item.item.private_message.creator_id}`
      : `/comment/${item.item.comment.id}`}
    size="sm"
    rounding="pill"
    class="shrink-0"
    onclick={() => markAsRead(true)}
  >
    Jump
  </Button>
{/snippet}

<Expandable open icon={false}>
  {#snippet title()}
    <div class="flex flex-row gap-2 items-center w-full">
      <div class="relative">
        <Avatar url={item.creator.avatar} width={28} alt={item.creator.name} />
        <Material
          color="uniform"
          padding="none"
          class="absolute -bottom-2 -right-2 p-1"
          rounding="full"
        >
          <Icon
            src={item.type == 'comment_reply'
              ? ChatBubbleOvalLeftEllipsis
              : item.type == 'person_mention'
                ? AtSymbol
                : PaperAirplane}
            size="12"
            micro
          />
        </Material>
      </div>
      <div class="flex flex-col">
        <div class="text-sm font-normal text-slate-600 dark:text-zinc-400">
          {#if item.type == 'comment_reply'}
            <Markdown
              inline
              source={`**${item.creator.name}** replied to you in **${escapeHtml(item.item.post.name)}**`}
              noStyle
            />
          {:else if item.type == 'person_mention'}
            <Markdown
              inline
              source={`**${item.creator.name}** mentioned you in **${escapeHtml(item.item.post.name)}**`}
              noStyle
            />
          {:else if item.type == 'private_message'}
            <Markdown
              inline
              source={`**${item.creator.name}** messaged **${escapeHtml(item.item.recipient.name)}**`}
              noStyle
            />
          {/if}
        </div>
        <div class="text-xs text-slate-600 dark:text-zinc-400">
          <RelativeDate date={publishedToDate(item.published)} />
        </div>
      </div>
      <div class="flex-1"></div>
      <ButtonGroup orientation="horizontal" class="md:flex hidden shrink-0">
        {@render actions()}
      </ButtonGroup>
    </div>
  {/snippet}
  {#snippet extended()}
    <ButtonGroup orientation="horizontal" class="flex md:hidden">
      {@render actions()}
    </ButtonGroup>
  {/snippet}
  {#snippet content()}
    {#if item.type == 'comment_reply' || item.type == 'person_mention'}
      <CommentItem
        comment={item.item}
        community={false}
        meta={false}
        class="py-0!"
        commentClass="py-0!"
      />
    {:else}
      <PrivateMessage message={item.item} meta={false} />
    {/if}
  {/snippet}
</Expandable>

<style>
  :global(strong) {
    font-weight: 600;
    color: var(--color-primary-900);
  }

  :global(.dark strong) {
    color: var(--color-primary-100);
  }
</style>
